"""Exam-style multiple-choice bank. The correct option of every code question is
checked against real Python output; distractors are common mistakes."""
import json, sys
sys.path.insert(0, ".")
from lib import run_snippet, norm

BANK = []
ERR = []


def C(topic, code, correct, wrong, why="", q="What is printed?", files=None):
    got = norm(run_snippet(code.strip() + "\n", files))
    if got != norm(correct):
        ERR.append(f"{topic}: {code!r}\n expected {correct!r}\n got {got!r}")
    for w in wrong:
        if norm(w) == norm(correct):
            ERR.append(f"{topic}: distractor equals answer {w!r}")
    BANK.append({"t": topic, "q": q, "code": code.strip(), "ok": correct, "bad": wrong, "why": why})


def T(topic, q, correct, wrong, why=""):
    BANK.append({"t": topic, "q": q, "code": None, "ok": correct, "bad": wrong, "why": why})


H = "What happens?"
